window.__votdWeek && window.__votdWeek({"week":"2028-09-18","reading":"3 Nephi 8–11","days":[{"d":"2028-09-18","ref":"3 Nephi 8:14","b":"3 Nephi","c":8,"v":14,"he":"וְעָרִים גְּדוֹלוֹת וְנוֹדָעוֹת רַבּוֹת שָׁקְעוּ וְרַבּוֹת נִשְׂרְפוּ וְרַבּוֹת נִרְעֲשׁוּ עַד־כִּי נָפְלוּ בִּנְיָנֵיהֶן אָרְצָה וְיוֹשְׁבֵיהֶן הוּמְתוּ וְהַמְּקוֹמוֹת נֶעֶזְבוּ שְׁמָמָה׃","en":"And many great and notable cities were sunk, and many were burned, and many were shaken till the buildings thereof had fallen to the earth, and the inhabitants thereof were slain, and the places were left desolate."},{"d":"2028-09-19","ref":"3 Nephi 9:13","b":"3 Nephi","c":9,"v":13,"he":"הוֹי כׇּל־אַתֶּם הַנִּמְלָטִים כִּי הֱיִיתֶם צַדִּיקִים מֵהֶם הֲלֹא תָשׁוּבוּ עַתָּה אֵלַי וְתָשׁוּבוּ מֵחַטֹּאתֵיכֶם וְתֵהָפְכוּ לְמַעַן אֶרְפָּא אֶתְכֶם׃","en":"O all ye that are spared because ye were more righteous than they, will ye not now return unto me, and repent of your sins, and be converted, that I may heal you?"},{"d":"2028-09-20","ref":"3 Nephi 9:19","b":"3 Nephi","c":9,"v":19,"he":"וְלֹא תַקְרִיבוּ לִי עוֹד שְׁפׇךְ־דָּם אַף זִבְחֵיכֶם וְעוֹלוֹתֵיכֶם יֶחְדָּלוּ כִּי־לֹא אֶקַּח מִזִּבְחֵיכֶם וְעוֹלוֹתֵיכֶם׃","en":"And ye shall offer up unto me no more the shedding of blood; yea, your sacrifices and your burnt offerings shall be done away, for I will accept none of your sacrifices and your burnt offerings."},{"d":"2028-09-21","ref":"3 Nephi 10:6","b":"3 Nephi","c":10,"v":6,"he":"הוֹי בֵּית־יִשְׂרָאֵל אֲשֶׁר חָמַלְתִּי עֲלֵיכֶם כַּמָּה פְעָמִים אֲקַבֵּץ אֶתְכֶם כַּאֲשֶׁר תְּקַבֵּץ תַּרְנְגֹלֶת אֶת־אֶפְרוֹחֶיהָ תַּחַת כְּנָפֶיהָ אִם־תָּשׁוּבוּ וְתָבוֹאוּ אֵלַי בְּכׇל־לְבַבְכֶם׃","en":"O ye house of Israel whom I have spared, how oft will I gather you as a hen gathereth her chickens under her wings, if ye will repent and return unto me with full purpose of heart."},{"d":"2028-09-22","ref":"3 Nephi 10:7","b":"3 Nephi","c":10,"v":7,"he":"וְאִם־לֹא בֵּית־יִשְׂרָאֵל מְקוֹמוֹת מוֹשְׁבוֹתֵיכֶם יִהְיוּ שְׁמָמָה עַד־בּוֹא הַבְּרִית לַאֲבוֹתֵיכֶם׃","en":"But if not, O house of Israel, the places of your dwellings shall become desolate until the time of the fulfilling of the covenant to your fathers."},{"d":"2028-09-23","ref":"3 Nephi 11:11","b":"3 Nephi","c":11,"v":11,"he":"וְהִנֵּה אָנֹכִי אוֹר הָעוֹלָם וְחַיָּיו וְשָׁתִיתִי מִכּוֹס הַמָּרוֹר אֲשֶׁר־נָתַן לִי הָאָב וּפֵאַרְתִּי אֶת־הָאָב בְּשֵׂאתִי אֶת־חֲטָאֵי הָעוֹלָם אֲשֶׁר בָּהֶם עָשִׂיתִי אֶת־רְצוֹן הָאָב בְּכֹל מֵרֹאשׁ׃","en":"And behold, I am the light and the life of the world; and I have drunk out of that bitter cup which the Father hath given me, and have glorified the Father in taking upon me the sins of the world, in the which I have suffered the will of the Father in all things from the beginning."},{"d":"2028-09-24","ref":"3 Nephi 11:29","b":"3 Nephi","c":11,"v":29,"he":"כִּי אָמֵן אָמֵן אֹמֵר אֲנִי לָכֶם כׇּל־אֲשֶׁר רוּחַ הַמְּרִיבָה בוֹ לֹא מִמֶּנִּי הוּא כִּי מִן־הַשָּׂטָן הוּא אֲבִי הַמְּרִיבָה וְהוּא מֵסִית אֶת־לְבַב בְּנֵי־הָאָדָם לָרִיב בְּאַף אִישׁ בְּרֵעֵהוּ׃","en":"For verily, verily I say unto you, he that hath the spirit of contention is not of me, but is of the devil, who is the father of contention, and he stirreth up the hearts of men to contend with anger, one with another."}]});
